package ultra.downloads;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.json.*;import java.util.*;import android.app.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28)
public class PlaylistMirrorTest {
 Activity c;
 @Before public void setup(){c=Robolectric.buildActivity(Activity.class).setup().get();app.revanced.extension.shared.utils.Utils.testContext=c;Library.prefs(c).edit().clear().commit();}
 @Test public void zeroDownloadedPlaylistsKeepLibraryNameArtAndOrder()throws Exception{PlaylistIndex.roster(c,Arrays.asList(new Catalog.Playlist("VLPLz","Z first","https://i.ytimg.com/vi/abcdefghijk/hqdefault.jpg"),new Catalog.Playlist("VLPLb","B second","")));assertEquals(Arrays.asList("PLz","PLb",UnmatchedDownloads.ID),new ArrayList<>(PlaylistIndex.groups(c).keySet()));assertEquals("Z first",PlaylistIndex.groups(c).get("PLz"));assertEquals("https://i.ytimg.com/vi/abcdefghijk/hqdefault.jpg",PlaylistIndex.art(c,"PLz"));assertTrue(PlaylistIndex.members(c,"PLz").isEmpty());}
 @Test public void songsKeepPlaylistOrderNotDownloadTimeAndMissingAreExplicit()throws Exception{PlaylistIndex.register("VLPLz","List");PlaylistIndex.record("PLz",Arrays.asList(new Catalog.Track("bbbbbbbbbbb","Second downloaded","Singer",""),new Catalog.Track("aaaaaaaaaaa","First downloaded","Singer",""),new Catalog.Track("ccccccccccc","Missing","Singer","")),true);Library.Item a=new Library.Item(),b=new Library.Item();a.id="aaaaaaaaaaa";b.id="bbbbbbbbbbb";a.state=b.state="done";ArrayList<Library.Item> rows=PlaylistIndex.ordered(c,"PLz",Arrays.asList(a,b),true);assertSame(b,rows.get(0));assertSame(a,rows.get(1));assertEquals("unavailable",rows.get(2).state);assertEquals("Missing",rows.get(2).title);assertEquals(2,PlaylistIndex.ordered(c,"PLz",Arrays.asList(a,b),false).size());}
 @Test public void partialNativePageCannotEraseCompleteMembership()throws Exception{PlaylistIndex.record("PLz",Arrays.asList(new Catalog.Track("aaaaaaaaaaa","One","",""),new Catalog.Track("bbbbbbbbbbb","Two","","")),true);PlaylistIndex.record("PLz",Arrays.asList(new Catalog.Track("aaaaaaaaaaa","One","","")),false);assertEquals(2,PlaylistIndex.total(c,"PLz"));}
 @Test public void libraryParserKeepsShelfRowsAndExcludesMenus()throws Exception{JSONObject row=new JSONObject().put("musicTwoRowItemRenderer",new JSONObject().put("title",new JSONObject().put("simpleText","My list")).put("navigationEndpoint",new JSONObject().put("browseEndpoint",new JSONObject().put("browseId","VLPLone"))));JSONObject body=new JSONObject().put("contents",new JSONObject().put("gridRenderer",new JSONObject().put("items",new JSONArray().put(row)))) .put("menu",row);Catalog.Roster out=new Catalog.Roster();Catalog.roster(body,out,0);assertTrue(out.shelf);assertEquals(1,out.rows.size());assertEquals("My list",out.rows.get("VLPLone").name);}
 @Test public void duplicatePlaylistEntriesStayVisibleInOrder()throws Exception{PlaylistIndex.record("PLz",Arrays.asList(new Catalog.Track("aaaaaaaaaaa","One","",""),new Catalog.Track("aaaaaaaaaaa","One","","")),true);Library.Item a=new Library.Item();a.id="aaaaaaaaaaa";assertEquals(2,PlaylistIndex.ordered(c,"PLz",Arrays.asList(a),true).size());}
 @Test public void emptySyncedRosterDoesNotResurrectOldPlaylists()throws Exception{PlaylistIndex.register("VLPLold","Old");PlaylistIndex.roster(c,Collections.<Catalog.Playlist>emptyList());assertEquals(Collections.singleton(UnmatchedDownloads.ID),PlaylistIndex.groups(c).keySet());}
}
